/**
 * SPEC §11.2: `fixtures/violations/` holds one planted record per rubric
 * rule. Each MUST fail with its exact error code — a violation that only
 * warns (or that fails with the wrong code) is a CI failure, so this test
 * asserts exact-code membership, not just "some violation happened".
 * Generated by `scripts/gen-fixtures.mts`; committed, not regenerated here.
 */
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { RunRecordSchema } from "../packages/dogwatch/src/record/schema.js";
import { verifyRecord } from "../packages/dogwatch/src/verify/rubric.js";

const FIXTURES_DIR = fileURLToPath(new URL("../fixtures/violations", import.meta.url));

/** file stem -> the exact code SPEC §7's table assigns that rule. */
const EXPECTED_CODE: Record<string, string> = {
  "r01-no-checks": "E_NO_CHECKS",
  "r01b-check-nonterminal": "E_CHECK_NONTERMINAL",
  "r02-orphan-finding": "E_ORPHAN_FINDING",
  "r03-unreported-check": "E_UNREPORTED_CHECK",
  "r04-unsourced-finding": "E_UNSOURCED_FINDING",
  "r05-no-absence-section": "E_NO_ABSENCE_SECTION",
  "r06-silent-skip": "E_SILENT_SKIP",
  "r07-action-unbacked": "E_ACTION_UNBACKED",
  "r08-gate-unbacked": "E_GATE_UNBACKED",
  "r09-cost-unbacked": "E_COST_UNBACKED",
  "r10-advisory-ungrounded": "E_ADVISORY_UNGROUNDED",
  "r11-chain-broken": "E_CHAIN_BROKEN",
  "r12-record-tampered": "E_RECORD_TAMPERED",
  "r13-manufactured-finding": "E_MANUFACTURED_FINDING",
  "r14-metric-as-finding": "E_METRIC_AS_FINDING",
  "r15-secret-leak": "E_SECRET_LEAK",
};

const files = readdirSync(FIXTURES_DIR).filter((f) => f.endsWith(".json"));

describe("fixtures/violations — every rubric rule R1-R15", () => {
  it("has a fixture for every rule id in the honesty rubric (SPEC §7)", () => {
    const stems = files.map((f) => f.replace(/\.json$/, ""));
    for (const expected of Object.keys(EXPECTED_CODE)) {
      expect(stems, `missing fixture for ${expected}`).toContain(expected);
    }
  });

  for (const file of files) {
    const stem = file.replace(/\.json$/, "");
    const expectedCode = EXPECTED_CODE[stem];

    it(`${file} fails verification with exactly ${expectedCode ?? "(unregistered — add it to EXPECTED_CODE)"}`, () => {
      expect(expectedCode, `${file} is not registered in EXPECTED_CODE`).toBeDefined();
      const raw: unknown = JSON.parse(readFileSync(join(FIXTURES_DIR, file), "utf8"));
      const parsed = RunRecordSchema.safeParse(raw);
      expect(parsed.success, `${file} is not even schema-valid: ${parsed.success ? "" : JSON.stringify(parsed.error.issues.slice(0, 3))}`).toBe(true);
      if (!parsed.success) return;

      // R13 only fires under --rerun-rules (SPEC §6); every other fixture is
      // checked in the default (fast, offline) mode dogwatch verify runs on
      // every push.
      const violations = verifyRecord(parsed.data, { rerunRules: stem === "r13-manufactured-finding" });
      const codes = violations.map((v) => v.code);

      // "a violation that only warns is a CI failure" (SPEC §11.2): there
      // must be at least one violation, and it must be the exact code —
      // not merely present among a pile of unrelated ones.
      expect(codes.length, `${file} produced zero violations — the plant did not take`).toBeGreaterThan(0);
      expect(codes, `${file} did not fail with its exact code`).toContain(expectedCode);
    });
  }
});
